<template><div class="admin-portal" :class="{ 'sb-min': sidebarMin, 'theme-smp': grade === 'SMP' }"><div class="app" id="app"><div id="sb-overlay" :class="{ show: sidebarOpen }" @click="sidebarOpen = false" /><AdminSidebar :open="sidebarOpen" @close="sidebarOpen = false" /><div class="app-main"><AdminTopbar @toggle-menu="toggleSidebar" /><main id="view"><slot /></main></div><nav id="mnav"><NuxtLink v-for="item in adminMobileNavigation" :key="item.id" :to="adminPath(item.id)" exact-active-class="on"><span class="mind" /><AdminIcon :name="item.icon" size="21" />{{ item.t }}</NuxtLink><button type="button" @click="sidebarOpen = true"><span class="mind" /><AdminIcon name="menu" size="21" />Menu</button></nav></div></div></template>
<script setup lang="ts">import { ref } from 'vue'; import AdminSidebar from '~/components/admin/AdminSidebar.vue'; import AdminTopbar from '~/components/admin/AdminTopbar.vue'; import AdminIcon from '~/components/admin/AdminIcon.vue'; import '~/assets/css/admin.css'; import { adminMobileNavigation } from '~/composables/useAdminNavigation'; import { useAdminGrade } from '~/composables/useAdminGrade'; const grade = useAdminGrade(); const sidebarMin=ref(false); const sidebarOpen=ref(false); const adminPath=(id:string)=>id==='dashboard'?'/admin':`/admin/${id}`; const toggleSidebar=()=>{if(window.innerWidth<=1024){sidebarOpen.value=!sidebarOpen.value}else{sidebarMin.value=!sidebarMin.value}}</script>

